package org.jsoup.select;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.TokenQueue;
import org.jsoup.select.Evaluator.EvaluatorType;
import org.jsoup.select.Evaluator.TextEvaluator;
import org.jsoup.select.Evaluator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class QueryParser_parse_TriageGen1Test {

    @Test
    public void testParseEmptyString() {
        Evaluator result = org.jsoup.select.QueryParser.parse("");
        assertTrue(result instanceof Evaluator.EvaluatorEmpty);
    }

    @Test
    public void testParseSingleTag() {
        Evaluator result = org.jsoup.select.QueryParser.parse("div");
        assertTrue(result instanceof Evaluator.TagEvaluator);
        assertEquals("div", ((Evaluator.TagEvaluator) result).getName());
    }

    @Test
    public void testParseSingleTagWithClass() {
        Evaluator result = org.jsoup.select.QueryParser.parse("div.className");
        assertTrue(result instanceof Evaluator.AndEvaluator);
        Evaluator.TagEvaluator tagEval = ((Evaluator.TagEvaluator) ((Evaluator.AndEvaluator) result).getLeft());
        assertEquals("div", tagEval.getName());
        assertTrue(((Evaluator.AndEvaluator) result).getRight() instanceof Evaluator.ClassEvaluator);
        Evaluator.ClassEvaluator classEval = (Evaluator.ClassEvaluator) ((Evaluator.AndEvaluator) result).getRight();
        assertEquals("className", classEval.getName());
    }

    @Test
    public void testParseIdSelector() {
        Evaluator result = org.jsoup.select.QueryParser.parse("#id");
        assertTrue(result instanceof Evaluator.IdEvaluator);
        assertEquals("id", ((Evaluator.IdEvaluator) result).getId());
    }

    @Test
    public void testParseAttributeSelector() {
        Evaluator result = org.jsoup.select.QueryParser.parse("[attribute='value']");
        assertTrue(result instanceof Evaluator.AttributeEvaluator);
        assertEquals("attribute", ((Evaluator.AttributeEvaluator) result).getName());
        assertEquals("value", ((Evaluator.AttributeEvaluator) result).getValue());
        assertEquals(Evaluator.AttributeEvaluator.EQUALS, ((Evaluator.AttributeEvaluator) result).getOperator());
    }

    @Test
    public void testParseAttributeContainsSelector() {
        Evaluator result = org.jsoup.select.QueryParser.parse("[attribute*=value]");
        assertTrue(result instanceof Evaluator.AttributeEvaluator);
        assertEquals("attribute", ((Evaluator.AttributeEvaluator) result).getName());
        assertEquals("value", ((Evaluator.AttributeEvaluator) result).getValue());
        assertEquals(Evaluator.AttributeEvaluator.CONTAINS, ((Evaluator.AttributeEvaluator) result).getOperator());
    }

    @Test
    public void testParseTextSelector() {
        Evaluator result = org.jsoup.select.QueryParser.parse(":contains('text')");
        assertTrue(result instanceof TextEvaluator);
        assertEquals("text", ((TextEvaluator) result).getPattern());
    }

    @Test
    public void testParseComplexSelector() {
        Evaluator result = org.jsoup.select.QueryParser.parse("div#id.className[attr='value']:contains('text')");
        assertTrue(result instanceof Evaluator.AndEvaluator);
        Evaluator left = ((Evaluator.AndEvaluator) result).getLeft();
        assertTrue(left instanceof Evaluator.AndEvaluator);

        Evaluator.TagEvaluator tagEval = (Evaluator.TagEvaluator) ((Evaluator.AndEvaluator) left).getLeft();
        assertEquals("div", tagEval.getName());

        Evaluator.IdEvaluator idEval = (Evaluator.IdEvaluator) ((Evaluator.AndEvaluator) left).getRight();
        assertEquals("id", idEval.getId());

        Evaluator right = ((Evaluator.AndEvaluator) result).getRight();
        assertTrue(right instanceof Evaluator.AndEvaluator);

        Evaluator.ClassEvaluator classEval = (Evaluator.ClassEvaluator) ((Evaluator.AndEvaluator) right).getLeft();
        assertEquals("className", classEval.getName());

        Evaluator.AttributeEvaluator attrEval = (Evaluator.AttributeEvaluator) ((Evaluator.AndEvaluator) right).getRight();
        assertEquals("attr", attrEval.getName());
        assertEquals("value", attrEval.getValue());
        assertEquals(Evaluator.AttributeEvaluator.EQUALS, attrEval.getOperator());

        assertTrue(((Evaluator.AndEvaluator) ((Evaluator.AndEvaluator) right).getRight()).getRight() instanceof TextEvaluator);
        TextEvaluator textEval = (TextEvaluator) ((Evaluator.AndEvaluator) ((Evaluator.AndEvaluator) right).getRight()).getRight();
        assertEquals("text", textEval.getPattern());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseInvalidSelector() {
        org.jsoup.select.QueryParser.parse(":invalid");
    }
}
